#include <iostream>
#include <string>
using namespace std;
typedef __int128 i128;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    while (q--) {
        string n, mode;
        long long bps;
        cin >> n >> bps >> mode;
        size_t dot = n.find('.');
        i128 cents = 0;
        for (size_t i = 0; i < n.size(); i++)
            if (i != dot) cents = cents * 10 + (n[i] - '0');
        i128 num = cents * bps;
        i128 qt = num / 10000, r = num % 10000;
        if (mode == "UP" && r >= 5000) qt++;
        else if (mode == "EVEN" && (r > 5000 || (r == 5000 && qt % 2 == 1))) qt++;
        long long w = (long long)(qt / 100), c = (long long)(qt % 100);
        cout << w << '.' << (c < 10 ? "0" : "") << c << '\n';
    }
    return 0;
}

